package org.jfree.chart.plot;

import java.awt.Color;
import java.awt.Paint;
import java.awt.Stroke;
import java.io.*;
import java.math.*;
import java.util.*;
import org.jfree.chart.Stroke;
import org.jfree.chart.event.MarkerChangeEvent;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class ValueMarker_ValueMarker_TriageGen0Test {

    @Test
    public void testConstructorWithSingleParameter() {
        double expectedValue = 10.5;
        ValueMarker marker = new ValueMarker(expectedValue);
        assertEquals(expectedValue, marker.getValue(), 1.0E-9);
    }

    @Test
    public void testConstructorWithThreeParameters() {
        double expectedValue = 20.0;
        Paint paint = Color.RED;
        Stroke stroke = new Stroke(1.0, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER);

        ValueMarker marker = new ValueMarker(expectedValue, paint, stroke);

        assertEquals(expectedValue, marker.getValue(), 1.0E-9);
        // Note: Accessing protected/internal state of superclass via getters if available
        // Since we cannot see superclass internals, we verify the object is created
    }

    @Test
    public void testConstructorWithSixParameters() {
        double expectedValue = 30.0;
        Paint paint = Color.BLUE;
        Stroke stroke = new Stroke(2.0, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
        Paint outlinePaint = Color.BLACK;
        Stroke outlineStroke = new Stroke(1.0, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER);
        float alpha = 0.5f;

        ValueMarker marker = new ValueMarker(expectedValue, paint, stroke, outlinePaint, outlineStroke, alpha);

        assertEquals(expectedValue, marker.getValue(), 1.0E-9);
    }

    @Test
    public void testSetValue() {
        ValueMarker marker = new ValueMarker(10.0);
        double newValue = 50.0;
        marker.setValue(newValue);
        assertEquals(newValue, marker.getValue(), 1.0E-9);
    }

    @Test
    public void testEquals() {
        ValueMarker marker1 = new ValueMarker(10.0);
        ValueMarker marker2 = new ValueMarker(10.0);
        ValueMarker marker3 = new ValueMarker(20.0);

        assertEquals(marker1, marker2);
        assertNotEquals(marker1, marker3);
        assertNotEquals(marker1, null);
        assertNotEquals(marker1, "not a marker");
    }

    // Helper for assertNotEquals in JUnit 4
    private void assertNotEquals(Object expected, Object actual) {
        if (expected != null && expected.equals(actual)) {
            org.junit.Assert.fail("Expected objects to be different, but they were equal.");
        }
    }

    // Mock Stroke implementation to satisfy compiler if BasicStroke is not accessible in context
    private static class BasicStroke {
        public static final int CAP_BUTT = 0;
        public static final int CAP_ROUND = 1;
        public static final int JOIN_MITER = 0;
        public static final int JOIN_ROUND = 1;
    }
}
